<span class="line">  <span class="token keyword">const</span> <span class="token punctuation">[</span>result<span class="token punctuation">,</span> executeMutation<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">useMutation</span><span class="token punctuation">(</span><span class="token constant">CREATE_USER</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
